# Non-ASCII, but considered `iswalnum()` in R with UTF-8 locale.
# Not considered `iswalnum()` in our scanner with C locale, but
# our overapproximation with `>= 128` allows this and aligns with R.
{
  if (TRUE) 1
  elseμ <- 1
