# Non-ASCII (U+00B7), rejected by R as syntax error since `iswalnum()` returns false.
# Our overapproximation with `>= 128` allows this, but that's ok since the R
# side behavior is a syntax error.
{
  if (TRUE) 1
  else· <- 1
}

